test "test_partition_report_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = PartitionReport{
        .partition_no = -123456,
        .report_index = -123456789,
